#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

int main() {
    vector<pair<double, double>> lines = {
        {3, 5},
        {4, 5},
        {9, -2},
        {1, -3},
        {1, -5}
    };

    int goodPairs = 0;

    for (int i = 0; i < lines.size(); i++) {
        for (int j = i + 1; j < lines.size(); j++) {
            double slope1 = lines[i].first;
            double slope2 = lines[j].first;
            double intercept1 = lines[i].second;
            double intercept2 = lines[j].second;

            if (slope1 == slope2) {
                // Parallel lines
                goodPairs++;
            } else if (slope1 * slope2 == -1) {
                // Perpendicular lines
                goodPairs++;
            }
        }
    }

    cout << "Number of good pairs: " << goodPairs << endl;

    return 0;
}

